//----W-Craft WebSquare 변환 확인: Filter----//
scwin.MxDataSet_code1_OnFilter = function(row) {
    if (dts_jongmok.NameValue(row, "SPOT_ISU_TRD_MKT_TP_CD") === scwin.gJongcode) return true;

    else return false;
};

scwin.grd_jongmok_OnKeyPress = function(kcode) {
