    if (window.event.keyCode === "13") {
        //JongmokName(window.event.keyCode);
        scwin.JongmokSearch();
    }
};

scwin.combo_market_onselchange = function(info) {
    if (scwin.ssMarket === "Y") {
        txb_jongmokName.setValue("");
        scwin.skw = "";
        scwin.tpcd = MxDataSet_code1.NameValue(combo_market.Index + 1, "CD_VAL");
        scwin.fn_list_sync();
    }
};

scwin.combo_stat_onselchange = function(info) {
    txb_jongmokName.setValue("");
    scwin.skw = "";

//----W-Craft WebSquare 변환 확인: ValueOfIndex----//
    scwin.stat = combo_stat.ValueOfIndex("Column2", combo_stat.Index);
    if (scwin.stat === '0') {
        scwin.stat = "";
    }
    scwin.fn_list_sync();
};

//----W-Craft WebSquare 변환 확인: Filter----//
scwin.dts_jongmok_OnFilter = function(row) {
    if (scwin.skw !== "") {
        f1 = (dts_jongmok.NameString(row, "COM_ABBRV")).toUpperCase();
        f2 = (dts_jongmok.NameString(row, "OLD_COM_ABBRV")).toUpperCase();
        if (f1.indexOf(scwin.skw) !== -1) {
            return true;
        } else if (f2.indexOf(scwin.skw) !== -1) {
            return true;
        } else {
            return false;
        }
    } else {
        return true;
    }
};

