scwin.fn_list_sync = function() {
    ////var url = "/isurcd.do?method=searchIsurCd&inputMessageId=isurcd&outputMessageId=isurcd" + "&LIST_STAT_CD=" + scwin.stat + "&SPOT_ISU_TRD_MKT_TP_CD=" + scwin.tpcd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const url = "/ui/dsclsrch/data/isurCode.jsp?method=searchIsurCd&inputMessageId=isurcd&outputMessageId=isurcd" + "&LIST_STAT_CD=" + scwin.stat + "&SPOT_ISU_TRD_MKT_TP_CD=" + scwin.tpcd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + $c.stf.info("SCREN_PROCS_TP_CD_01");
    ////dts_jongmok.DataID = encodeURI(url);

//----W-Craft WebSquare 변환 확인: reset----//
    ////dts_jongmok.reset();
    ////$c.cm.ShowWin(grd_jongmok);

    let smbObj = $p.getComponentById("sbm_dts_jongmok");
    smbObj.action = url;
    $c.sbm.execute(sbm_dts_jongmok)
};

/********************************************** 
 * 함수명   : Jongmok()
 * 설명       : 가나다라..검색
 ***********************************************/
scwin.Jongmok = function(prevval, nextval) {
    txb_jongmokName.setValue("");
    scwin.skw = "";

//----W-Craft WebSquare 변환 확인: Filter----//
    dts_jongmok.UseFilter = "true";

//----W-Craft WebSquare 변환 확인: Filter----//
    dts_jongmok.Filter();
    grd_jongmok.Redraw = "false";
    dts_jongmok.SortExpr = "+COM_ABBRV";
    dts_jongmok.Sort();
    let cnt = 0;
    for (i = 1; i <= dts_jongmok.countrow; i++) {
        let name = dts_jongmok.NameValue(i, "COM_ABBRV").substring(0, 1);
        if (name >= prevval && name < nextval) {
            cnt = i;
            break;
        }
    }
    grd_jongmok.Redraw = "true";
    dts_jongmok.Rowposition = cnt + 11;
    dts_jongmok.Rowposition = cnt;

//----W-Craft WebSquare 변환 확인: focus----//
    grd_jongmok.focus();
};

/********************************************** 
 * 함수명   : JongmokName()
 * 설명       : 종목명검색
 ***********************************************/
scwin.JongmokName = function(keyCode) {
    //if(keyCode==13) on_close();
    grd_jongmok.Redraw = "false";
    dts_jongmok.SortExpr = "+COM_ABBRV";
    dts_jongmok.Sort();
    let cnt = 0;
    const len = txb_jongmokName.getValue().length;
    const txtVal = txb_jongmokName.getValue().toUpperCase();
    for (i = 1; i <= dts_jongmok.countrow; i++) {
        let name = dts_jongmok.NameValue(i, "COM_ABBRV").substring(0, len).toUpperCase();
        if (txtVal <= name) {
            cnt = i;
            break;
        }
    }
    grd_jongmok.Redraw = "true";
    dts_jongmok.Rowposition = cnt + 11;
    dts_jongmok.Rowposition = cnt;
};

/********************************************** 
 * 함수명   : JongmokSearch()
 * 설명       : 종목명검색
 ***********************************************/
scwin.JongmokSearch = function() {
    scwin.skw = (txb_jongmokName.getValue()).toUpperCase();

//----W-Craft WebSquare 변환 확인: Filter----//
    ////dts_jongmok.UseFilter = "true";

//----W-Craft WebSquare 변환 확인: Filter----//
    ////dts_jongmok.Filter();
    ////dts_jongmok.Rowposition = 1;
};

/********************************************** 
 * 함수명   : Confirm()
 * 설명       : 부모창으로 종목코드 전달
 ***********************************************/
scwin.Confirm = async function() {
    //frame.Provider("../").종목코드id
    const pJongCode = dts_jongmok.NameValue(dts_jongmok.RowPosition, "ISUR_CD");
    const pJongNm = dts_jongmok.NameValue(dts_jongmok.RowPosition, "COM_ABBRV");
    const ld_mkt_tp_cd = dts_jongmok.NameValue(dts_jongmok.RowPosition, "SPOT_ISU_TRD_MKT_TP_CD");
    $c.frame.path("../").isurSearch_Rtn(pJongCode, pJongNm, ld_mkt_tp_cd);

//----W-Craft WebSquare 변환 확인: CloseFrame----//
    await $c.frame.CloseFrame();
};

