scwin.marketSetCombo = function() {
    let cIndex;
    let name;
    if (scwin.tpcd !== "") {
        for (i = 1; i <= MxDataSet_code1.countrow; i++) {
            name = MxDataSet_code1.NameValue(i, "CD_VAL");
            if (name === scwin.tpcd) {
                cIndex = i - 1;
                break;
            }
        }
        combo_market.Index = cIndex;
    }
    if (scwin.tpcd === "1" || scwin.tpcd === "2") {
        combo_market.setDisabled(true);
    }
    scwin.ssMarket = "Y";
};
